      "name": "discharge",
      "type": "continuous",
      "shape": [12],
      "lb": 0.0,
      "ub": 1.2
    },
    {
      "name": "grid",
      "type": "continuous",
      "shape": [12],
      "lb": 0.0,
      "ub": [3.4, 3.2, 2.9, 2.7, 2.5, 2.4, 2.4, 2.6, 2.8, 3.0, 3.1, 3.2]
    },
    {
      "name": "soc",
      "type": "continuous",
      "shape": [12],
      "lb": 0.0,
      "ub": 4.6
    }
  ],
  "constraints": [
    {
      "name": "power_balance",
      "type": "equality",
      "expr": "LOAD[t] == PV[t] + grid[t] + discharge[t] - charge[t]",
      "forall": "t in 0..11"
    },
    {
      "name": "soc_dynamics",
      "type": "equality",
      "expr": "soc[t] == (SOC0 if t == 0 else soc[t-1]) + charge[t] - discharge[t]",
      "forall": "t in 0..11"
    },
    {
      "name": "terminal_soc",
      "type": "inequality",
      "expr": "soc[11] >= SOC_MIN_TERMINAL"
    },
    {
      "name": "discharge_budget",
      "type": "inequality",
      "expr": "sum(discharge[t] for t in 0..11) <= DISCHARGE_BUDGET"
    }
  ],
  "objective": {
    "name": "minimize_cost",
    "expr": "sum(PRICE[t] * grid[t] for t in 0..11)",
    "sense": "min"
  }
}

